#include <array>
#include <iostream>

struct SensorSample { int milli_celsius; };
int main() {
    constexpr std::array<SensorSample, 3> samples{{{20100}, {20200}, {19900}}};
    int total = 0;
    for (const auto& sample : samples) total += sample.milli_celsius;
    std::cout << "average_milli_celsius=" << total / static_cast<int>(samples.size()) << '\n';
}
